/* Public demo uses memory; the private pilot uses an authenticated database adapter. */
(function(){
'use strict';
const D=window.ResponseDesk,X=window.XLSX,screen=document.getElementById('screen');
const isPilot=document.body.dataset.pilot==='true';
let cases=isPilot?[]:D.sampleCases(),view='today',selected='',queue={openOnly:true},handover={openOnly:true},book=null,matrix=[],sheetName='',header=0,mapping={},preview=null,fileName='',sequence=107,readSequence=0,cloud=null,client=null,pilotProfile=null,busy=false;
const tz=Intl.DateTimeFormat().resolvedOptions().timeZone||'Local timezone';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const date=s=>s?new Date(s).toLocaleString(undefined,{month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}):'No due date';
const localInput=s=>{if(!s)return '';const d=new Date(s);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}T${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`;};
const options=(list,value,empty)=>`${empty!==undefined?`<option value="">${esc(empty)}</option>`:''}${list.map(v=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(v)}</option>`).join('')}`;
const owners=()=>[...new Set(['Alex','Sam',...cases.map(c=>c.owner)].filter(Boolean))].sort();
const badge=c=>`<span class="badge ${c.category==='Complaint'?'complaint':''}">${esc(c.category)}</span><span class="badge ${c.state.startsWith('Waiting')?'waiting':c.state==='Resolved'?'resolved':''}">${esc(c.state)}</span>${c.escalated?'<span class="badge escalated">Escalated</span>':''}`;
const heading=(kicker,title,subtitle,action='')=>`<header class="page-heading"><div><p class="eyebrow">${kicker}</p><h1 tabindex="-1">${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</header>`;
function notify(message,error=false){const n=document.getElementById('notice');n.textContent=message;n.className=error?'error':'';n.hidden=false;}
async function attempt(fn){if(busy)return;busy=true;document.querySelector('.app-shell').inert=true;try{await fn();}catch(e){notify(e.message,true);}finally{busy=false;document.querySelector('.app-shell').inert=false;}}
function nextId(){return isPilot?'RD-'+crypto.randomUUID().replace(/-/g,'').slice(0,12).toUpperCase():`RD-${sequence++}`;}
async function persist(records){if(!isPilot)return records;notify('Saving to the pilot database…');return cloud.save(records);}
function navigate(next,id){view=next;if(id)selected=id;document.getElementById('notice').hidden=true;render();screen.querySelector('h1')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function render(){document.getElementById('open-count').textContent=D.counts(cases).open;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));if(isPilot&&!pilotProfile){renderLogin();return;}if(view==='today')renderToday();else if(view==='add')renderAdd();else if(view==='case')renderCase();else if(view==='import')renderImport();else renderHandover();if(isPilot)screen.querySelector('.story')?.remove();}
function stats(items,buttons=false){const s=D.counts(items);return `<div class="stats">${[['open',s.open,'Open cases',''],['complaints',s.complaints,'Open complaints','teal'],['overdue',s.overdue,'Overdue follow-ups','red'],['unassigned',s.unassigned,'Unassigned cases','']].map(([key,value,title,colour])=>`<${buttons?'button':'div'} class="stat" ${buttons?`data-stat="${key}" aria-label="Show ${title.toLowerCase()}"`:''}><b class="${colour}">${value}</b><span>${title}</span></${buttons?'button':'div'}>`).join('')}</div>`;}
function filterToolbar(f,kind){return `<div class="toolbar" data-filter-group="${kind}"><label class="search">Search cases<input type="search" name="search" value="${esc(f.search||'')}" placeholder="Customer, subject or reference" aria-label="Search cases"></label><label>Queue<select name="state">${options(D.STATES,f.state,'All states')}</select></label><label>Owner<select name="owner">${options(owners(),f.owner,'All owners')}</select></label><label>Category<select name="category">${options(['Enquiry','Complaint'],f.category,'Both categories')}</select></label>${kind==='queue'?`<button class="filter-button ${f.overdue?'active':''}" data-toggle="overdue" aria-pressed="${!!f.overdue}">Overdue</button><button class="filter-button ${f.unassigned?'active':''}" data-toggle="unassigned" aria-pressed="${!!f.unassigned}">Unassigned</button><button class="filter-button" data-clear-filters>Clear</button>`:''}</div>`;}
function sorted(items){return items.slice().sort((a,b)=>Number(D.overdue(b))-Number(D.overdue(a))||Number(!b.owner)-Number(!a.owner)||(Date.parse(a.due)||Infinity)-(Date.parse(b.due)||Infinity));}
function cards(items){return items.length?sorted(items).map(c=>`<button class="case-card ${D.overdue(c)?'overdue':''}" data-case="${esc(c.id)}" aria-label="Open ${esc(c.id+' '+c.subject)}"><div><div class="reference">${esc(c.id)} · ${esc(c.externalRef||'No external reference')}</div><h3>${esc(c.subject)}</h3><p>${esc(c.customer)} · ${esc(c.owner||'Unassigned')}</p><div style="margin-top:8px">${badge(c)}</div></div><div class="next"><strong>Next action</strong>${esc(c.state==='Resolved'?'Completed':c.nextAction||'Set the first step')}</div><div class="due"><strong>${c.state==='Resolved'?'Resolved':D.overdue(c)?'Overdue follow-up':'Next check-in'}</strong>${c.state==='Resolved'?date(c.updatedAt):date(c.due)} <span aria-hidden="true">↗</span></div></button>`).join(''):'<div class="empty">No cases match these filters. Try another queue or clear the filters.</div>';}
function refreshQueue(){if(isPilot)screen.querySelector('.story')?.remove();const items=D.filter(cases,queue);document.getElementById('queue-list').innerHTML=cards(items);document.getElementById('queue-total').textContent=`${items.length} cases · due dates in ${tz}`;}
function renderToday(){const scenario=cases.find(c=>c.id==='RD-101');screen.innerHTML=heading('Customer response desk','Keep the next step in sight.','Enquiries and complaints, with a clear owner and follow-up.',`<button class="btn primary" data-view="add">＋ Add a case</button>`)+stats(cases,true)+`<section class="story"><div><p class="eyebrow">Try the workflow</p><h3>One delivery. Two conversations. One case.</h3><p>Open Maya’s enquiry, record a damaged-item complaint, draft a reply, then resolve or reopen it. The history stays together.</p></div><button class="btn teal" data-case="${esc(scenario?.id||'RD-101')}">Explore the sample ↗</button></section>`+filterToolbar(queue,'queue')+`<div class="actions"><label class="check"><input type="checkbox" id="show-resolved" ${!queue.openOnly?'checked':''}> Include resolved cases</label></div><div class="queue-header"><h2>Your case queue</h2><span id="queue-total"></span></div><section id="queue-list" class="case-list" aria-label="Case queue"></section>`;refreshQueue();}
function field(key,value='',prefix='new',required=false){const label=D.FIELDS[key];let control;if(key==='category')control=`<select name="${key}" id="${prefix}-${key}">${options(['Enquiry','Complaint'],value||'Enquiry')}</select>`;else if(key==='state')control=`<select name="${key}" id="${prefix}-${key}">${options(D.STATES.filter(s=>s!=='Resolved'),value||'New')}</select>`;else if(['summary','nextAction','waitingReason','remedy'].includes(key))control=`<textarea name="${key}" id="${prefix}-${key}" ${required?'required':''} rows="${key==='summary'?3:2}">${esc(value)}</textarea>`;else control=`<input id="${prefix}-${key}" name="${key}" type="${key==='due'?'datetime-local':'text'}" value="${esc(key==='due'?localInput(value):value)}" ${required?'required':''} ${key==='owner'?'list="owner-list"':''} maxlength="${key==='subject'?180:500}">`;return `<label class="${['summary','nextAction','waitingReason','remedy'].includes(key)?'full':''}" for="${prefix}-${key}">${label}${required?' *':''}${control}${key==='due'?`<span class="help">Local time: ${esc(tz)}</span>`:''}</label>`;}
const ownerList=()=>`<datalist id="owner-list">${owners().map(o=>`<option value="${esc(o)}">`).join('')}</datalist>`;
function renderAdd(){screen.innerHTML=heading('01 / Intake','Start with the conversation.','Paste an enquiry or complaint. No spreadsheet needed.')+`<form id="add-form" class="panel"><div class="step-label">Customer &amp; context</div><div class="form-grid">${['customer','contact','category','source','subject','externalRef','summary','remedy'].map(k=>field(k,k==='source'?'Manual':'','new',['customer','subject','summary'].includes(k))).join('')}</div><div class="section-line"><div class="step-label">Ownership &amp; next step</div><p class="help">New cases can be saved before assignment. Every active or waiting case needs an owner, action and due date.</p><div class="form-grid" style="margin-top:14px">${['owner','state','nextAction','due','waitingReason'].map(k=>field(k,'','new')).join('')}</div></div><div class="actions section-line"><button type="submit" class="btn primary">Create case</button><button type="button" class="btn" data-view="today">Cancel</button></div>${ownerList()}</form>`;}
function renderCase(){const c=cases.find(c=>c.id===selected);if(!c){navigate('today');return;}const resolved=c.state==='Resolved';screen.innerHTML=heading(`${esc(c.id)} · ${esc(c.externalRef||'No external reference')}`,esc(c.subject),esc(c.customer),'<button class="btn" data-view="today">← Back to queue</button>')+`<div class="workspace"><div><section class="panel">${badge(c)}<p class="case-summary">${esc(c.summary)}</p><div class="metadata"><span>Owner: <strong>${esc(c.owner||'Unassigned')}</strong></span><span>Contact: <strong>${esc(c.contact||'Not supplied')}</strong></span><span>Source: <strong>${esc(c.source)}</strong></span></div>${c.remedy?`<p class="help">Requested remedy: ${esc(c.remedy)}</p>`:''}<div class="next-highlight"><p class="step-label">${resolved?'Resolution':'Next step'}</p><b>${esc(resolved?c.resolution:c.nextAction||'Assign an owner and set the first step')}</b><p class="help">${resolved?'Closed '+date(c.updatedAt):`${D.overdue(c)?'Overdue · ':''}${date(c.due)} · ${esc(tz)}`}</p>${c.waitingReason&&!resolved?`<p class="help">Waiting: ${esc(c.waitingReason)}</p>`:''}${c.escalated?`<p class="help">Escalation: ${esc(c.escalationReason)}</p>`:''}</div>${c.id==='RD-101'&&!resolved?`<div class="story" style="padding:14px;margin:0"><div><h3>Continue Maya’s scenario</h3><p>${c.category==='Enquiry'?'The parcel arrives, but the item is damaged. Convert this enquiry and record what changed.':'The complaint is recorded. Draft a reply and arrange a replacement, then record the outcome.'}</p></div>${c.category==='Enquiry'?'<button class="btn teal" data-scenario>Record complaint</button>':''}</div>`:''}<details ${resolved?'':'open'}><summary>${resolved?'Case details':'Update ownership & next action'}</summary><form id="edit-form"><div class="form-grid">${(resolved?['category','owner','contact','remedy']:['category','state','owner','due','nextAction','waitingReason','remedy']).map(k=>field(k,c[k],'edit')).join('')}</div><button class="btn primary" style="margin-top:14px" type="submit">Save changes</button></form></details><details><summary>Add a note or customer update</summary><form id="note-form"><label>Type<select name="kind">${options(['Internal note','Customer update'],'Internal note')}</select></label><label style="margin-top:10px">What changed?<textarea name="text" required rows="3" placeholder="Keep a useful record of the conversation or internal decision."></textarea></label><button class="btn" type="submit" style="margin-top:12px">Add to history</button></form></details>${resolved?`<details open><summary>Reopen this case</summary><form id="reopen-form"><div class="form-grid"><label class="full">Reason<textarea name="reason" required></textarea></label>${['owner','nextAction','due'].map(k=>field(k,k==='owner'?c.owner:'','reopen',true)).join('')}</div><button class="btn primary" type="submit" style="margin-top:14px">Reopen with next action</button></form></details>`:`<details><summary>Escalate or resolve</summary><form id="escalate-form"><label>Escalation reason<textarea name="reason" required></textarea></label><p class="help">The assigned owner remains accountable for the next step.</p><button class="btn danger" type="submit" style="margin-top:12px">Flag escalation</button></form><form id="resolve-form" class="section-line"><label>Resolution outcome<textarea name="outcome" required placeholder="What was done and how was the customer informed?"></textarea></label><label class="check"><input name="confirmed" type="checkbox" required> I confirm the agreed action is complete and the customer has been informed.</label><button class="btn teal" type="submit">Resolve case</button></form></details>`}</section><section class="panel"><p class="step-label">Customer reply</p><h2>Draft, review, then respond.</h2><p class="help">Prepare the reply here. Send it through your usual channel.</p><form id="draft-form"><label style="margin-top:13px">Reply draft<textarea name="text" id="reply-draft" rows="6" placeholder="Write your reply or start from the template.">${esc(c.draft)}</textarea></label><div class="actions" style="margin-top:12px"><button class="btn" type="button" data-template>Use reply template</button><button class="btn" type="button" data-copy>Copy draft</button><button class="btn primary" type="submit">Save draft</button></div></form><details><summary>Record a message already sent</summary><form id="sent-form"><label>Message sent elsewhere<textarea name="text" required>${esc(c.draft)}</textarea></label><label class="check"><input name="confirmed" type="checkbox" required> This message was already sent outside this prototype.</label><button class="btn" type="submit">Record sent message</button></form></details></section></div><section class="panel"><p class="step-label">Case history</p><h2>The whole conversation.</h2><p class="help" style="margin-bottom:21px">Newest first · ${c.timeline.length} events · ${esc(tz)}</p><ol class="timeline">${c.timeline.slice().reverse().map(e=>`<li><span class="time">${date(e.at)}</span><h3>${esc(e.type)}</h3><p>${esc(e.text)}</p></li>`).join('')}</ol></section></div>${ownerList()}`;}
function readMatrix(name,nextBook=book){const sheet=nextBook.Sheets[name];if(!sheet||!sheet['!ref'])throw Error('This worksheet is empty.');const r=X.utils.decode_range(sheet['!ref']);if(r.e.r>2200||r.e.c>49)throw Error('Use a sheet with at most 2,201 rows and 50 columns, including headings.');const nextMatrix=Array.from({length:r.e.r+1},(_,row)=>Array.from({length:r.e.c+1},(_,col)=>sheet[X.utils.encode_cell({r:row,c:col})]||null));book=nextBook;matrix=nextMatrix;sheetName=name;header=r.s.r;guessMapping();preview=null;}
function guessMapping(){mapping={};const aliases={externalRef:['reference','ref','externalref','externalreference','caseid'],customer:['customer','customername','name'],contact:['contact','email','phone'],category:['category','type'],subject:['subject','title'],summary:['summary','message','description'],source:['source','channel'],remedy:['requestedremedy','remedy'],owner:['owner','assignee','assignedto'],state:['state','status'],nextAction:['nextaction','action'],due:['nextdue','due','duedate','nextdueutc'],waitingReason:['waitingreason','reasonforwaiting']};for(const [k,values]of Object.entries(aliases)){const index=matrix[header]?.findIndex(c=>values.includes(String(c?.v??'').toLowerCase().replace(/[^a-z]/g,'')));if(index>=0)mapping[k]=index;}}
function renderImport(){screen.innerHTML=heading('02 / Import & review','Bring your existing queue.','Choose a worksheet, map the columns and review rows before creating cases.')+`<section class="panel"><div class="step-label">1 · Choose a file</div><h2>Excel first. CSV works too.</h2><p class="subtitle">Open cases only · up to 2,000 data rows · 10 MB per file.</p><div class="actions"><button class="btn" data-download-template>Download Excel template ↓</button><button class="btn" data-import-example>Try a sample workbook</button></div><div class="drop-area"><label for="import-file">Upload .xlsx or .csv<input id="import-file" type="file" accept=".xlsx,.csv"></label><p class="help">Dates: YYYY-MM-DD, ISO timestamps or Excel dates. Date-only values use 23:59; Excel dates and timestamps without an offset use ${esc(tz)}. Formula cells need cached values; formulas are never executed.</p></div>${book?`<div class="file-info">${esc(fileName)} · ${book.SheetNames.length} worksheet(s)</div><div class="form-grid"><label>Worksheet<select id="import-sheet">${options(book.SheetNames,sheetName)}</select></label><label>Header row<input id="import-header" type="number" min="1" max="${matrix.length}" value="${header+1}"></label></div>`:''}</section>${book?`<section class="panel"><div class="step-label">2 · Map columns</div><p class="help" style="margin-bottom:16px">Customer, subject and summary are required. Unmapped category/state default to Enquiry/New. Reference matching is case-insensitive. Rows without a reference cannot be deduplicated; review them carefully.</p><div class="mapping">${Object.entries(D.FIELDS).map(([key,label])=>`<label>${label}${['customer','subject','summary'].includes(key)?' *':''}<select data-map="${key}"><option value="">Not mapped</option>${(matrix[header]||[]).map((c,i)=>`<option value="${i}" ${String(mapping[key])===String(i)?'selected':''}>${X.utils.encode_col(i)} · ${esc(c?.v??'(blank)')}</option>`).join('')}</select></label>`).join('')}</div><div class="actions section-line"><button class="btn primary" data-preview>Review rows</button></div></section><section id="import-review"></section>`:''}`;if(preview)renderPreview();}
function review(){if(!['customer','subject','summary'].every(k=>mapping[k]!==undefined&&mapping[k]!==''))throw Error('Map Customer, Subject and Summary before reviewing.');const chosen=Object.values(mapping).filter(v=>v!==undefined&&v!=='').map(String);if(new Set(chosen).size!==chosen.length)throw Error('Map each source column only once.');return D.reviewImport(matrix,header,mapping,cases,!!book.Workbook?.WBProps?.date1904);}
function renderPreview(){const ok=preview.filter(r=>r.valid),bad=preview.length-ok.length;document.getElementById('import-review').innerHTML=`<section class="panel"><div class="step-label">3 · Review & import</div><h2>${ok.length} ready · ${bad} need attention</h2><p class="subtitle">Only valid rows will be created. Duplicate references are skipped, never merged or overwritten. Matching customer names stay as separate cases.</p><div class="table-wrap"><table><thead><tr><th>Row</th><th>Customer / subject</th><th>Reference</th><th>Next due</th><th>Review</th></tr></thead><tbody>${preview.slice(0,100).map(r=>`<tr><td>${r.row}</td><td>${esc(r.data.customer)}<br>${esc(r.data.subject)}</td><td>${esc(r.data.externalRef||'No reference')}</td><td>${r.data.due?date(r.data.due):'—'}</td><td class="${r.valid?'success-text':'issue'}">${r.valid?'Ready':r.errors.map(esc).join('<br>')}</td></tr>`).join('')}</tbody></table></div>${preview.length>100?`<p class="help">Showing the first 100 of ${preview.length} rows. Download the full review for every row.</p>`:''}<div class="actions"><button class="btn primary" data-commit-import ${!ok.length?'disabled':''}>Import ${ok.length} valid cases</button><button class="btn" data-export-review>Download review .xlsx ↓</button></div><p class="help" style="margin-top:12px">Correct invalid values in the source file and upload again. Reusing a reference protects existing cases.</p></section>`;}
function filteredHandover(){return D.filter(cases,handover);}
function renderHandover(){const items=filteredHandover();screen.innerHTML=heading('03 / Handover','Leave a clear next step.','A focused snapshot for the next person or shift.',`<button class="btn primary" data-export-handover ${!items.length?'disabled':''}>Download handover .xlsx ↓</button>`)+`<section class="panel"><div class="step-label">Choose the handover scope</div><p class="help" style="margin-bottom:14px">Open cases only. Date filters apply to the next due date; undated cases appear when no date range is set.</p>${filterToolbar(handover,'handover')}<div class="form-grid"><label>Next due from<input type="date" id="handover-from" value="${esc(handover.from||'')}"></label><label>Next due through<input type="date" id="handover-to" value="${esc(handover.to||'')}"></label></div><p class="help" style="margin-top:10px">${esc(tz)} · export includes UTC deadlines, generation time, filters and case history.</p></section><div id="handover-results">${stats(items)}<div class="queue-header"><h2>Handover preview</h2><span>${items.length} open cases · ${D.counts(items).enquiries} enquiries</span></div><section class="case-list">${cards(items)}</section></div>`;}
function refreshHandover(){const items=filteredHandover();document.getElementById('handover-results').innerHTML=stats(items)+`<div class="queue-header"><h2>Handover preview</h2><span>${items.length} open cases · ${D.counts(items).enquiries} enquiries</span></div><section class="case-list">${cards(items)}</section>`;screen.querySelector('[data-export-handover]').disabled=!items.length;}
function downloadWorkbook(sheets,name){if(!X)throw Error('The Excel parser did not load. Reload the page.');const wb=X.utils.book_new();for(const [title,rows]of Object.entries(sheets)){const ws=Array.isArray(rows[0])?X.utils.aoa_to_sheet(rows):X.utils.json_to_sheet(rows);ws['!cols']=Array.from({length:30},(_,i)=>({wch:i<3?23:34}));X.utils.book_append_sheet(wb,ws,title);}X.writeFile(wb,name,{bookType:'xlsx',compression:true});}
function template(){return {Instructions:[['Customer Response Desk · open case import'],['Required columns: Customer, Subject, Summary'],['Category: Enquiry or Complaint. State: New, Needs action, Waiting for customer, Waiting for team'],['Active/waiting cases need Owner, Next action and Next due. Waiting cases also need Waiting reason.'],['Dates: YYYY-MM-DD (23:59 local), ISO timestamp with offset, or Excel dates (local).'],['Reference is optional; use a stable unique reference to prevent duplicate imports.'],['Formula cells require cached values. Correct invalid rows and re-import; existing cases are never overwritten.']],Cases:[['Reference','Customer','Contact','Category','Subject','Summary','Source','Requested remedy','Owner','State','Next action','Next due','Waiting reason'],['DEMO-301','Zoe Taylor','zoe@example.invalid','Enquiry','Delivery update','Customer requests delivery status.','Email','','Alex','Needs action','Check courier tracking',new Date(Date.now()+86400000).toISOString(),''],['DEMO-302','Oliver King','oliver@example.invalid','Complaint','Item arrived damaged','Customer requests a replacement.','Phone','Replacement','Sam','Waiting for team','Confirm replacement stock',new Date(Date.now()+172800000).toISOString(),'Waiting for warehouse']]};}
function loadExample(){const wb=X.utils.book_new();for(const [name,rows]of Object.entries(template()))X.utils.book_append_sheet(wb,X.utils.aoa_to_sheet(rows),name);book=wb;fileName='Sample workbook (fictional)';readMatrix('Cases');renderImport();}
async function saveAction(action,payload){const index=cases.findIndex(c=>c.id===selected),candidate=D.apply(cases[index],action,payload);const [saved]=await persist([candidate]);cases[index]=saved;renderCase();document.getElementById('open-count').textContent=D.counts(cases).open;notify(action==='draft'?'Draft saved. No message has been sent.':action==='sent'?'Already-sent message recorded in the history.':'Case history updated.');}
function clearPilot(){readSequence++;cases=[];book=null;matrix=[];preview=null;mapping={};fileName='';selected='';pilotProfile=null;view='today';document.getElementById('pilot-identity').textContent='Private pilot · sign-in required';document.getElementById('sign-out').hidden=true;document.getElementById('refresh-pilot').hidden=true;document.getElementById('team-access').hidden=true;render();}
function renderLogin(){screen.innerHTML=heading('Private team pilot','Your queue. Safely saved.','Sign in with an approved pilot account to access enquiries and complaints.')+`<section class="panel" style="max-width:520px"><h2>Team sign-in</h2><form id="login-form"><label>Email<input type="email" name="email" autocomplete="username" required></label><label style="margin-top:15px">Password<input type="password" name="password" autocomplete="current-password" required></label><button class="btn primary" type="submit" style="margin-top:18px">Sign in</button></form><p class="help" style="margin-top:18px">Use the pilot login created by your administrator. This is separate from your Supabase dashboard account. Only approved, confirmed email addresses can access cases.</p><a class="btn" style="margin-top:20px" href="customer-response-desk.html">Explore the public demo ↗</a></section>`;}
async function loadPilot(){const profile=await cloud.profile(),records=await cloud.load();pilotProfile=profile;cases=records;document.getElementById('pilot-identity').textContent=`Private pilot · ${profile.label}`;document.getElementById('sign-out').hidden=false;document.getElementById('refresh-pilot').hidden=false;document.getElementById('team-access').hidden=profile.role!=='owner';render();}
async function renderTeam(){if(pilotProfile?.role!=='owner')throw Error('Pilot owner access required.');const members=await cloud.members();screen.innerHTML=heading('Pilot administration','Keep access deliberate.','Grant or revoke access for a confirmed email. No invitation email is sent.')+`<section class="panel"><h2>Approved accounts</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Access</th></tr></thead><tbody>${members.map(m=>`<tr><td>${esc(m.label)}</td><td>${esc(m.email)}</td><td>${esc(m.role)}</td><td>${m.enabled?'Enabled':'Disabled'}</td></tr>`).join('')}</tbody></table></div><form id="member-form"><div class="form-grid"><label>Email<input name="p_email" type="email" required></label><label>Name<input name="p_label" maxlength="100" required></label><label>Role<select name="p_role">${options(['agent','owner'],'agent')}</select></label><label>Access<select name="p_enabled"><option value="true">Enabled</option><option value="false">Disabled</option></select></label></div><p class="help" style="margin:15px 0">First create the person's login in Supabase Authentication → Users. To update access, enter the same email here. An owner can manage access for the entire pilot team.</p><button class="btn primary" type="submit">Save access</button></form></section><button class="btn" data-view="today">← Back to queue</button>`;}
async function initPilot(){if(!window.supabase||!window.ResponseDeskConfig||!window.ResponseDeskCloud)throw Error('The sign-in components did not load. Reload this page.');const config=window.ResponseDeskConfig;client=window.supabase.createClient(config.url,config.publishableKey,{auth:{storage:window.sessionStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:false},global:{fetch:(url,options={})=>fetch(url,{...options,signal:options.signal?AbortSignal.any([options.signal,AbortSignal.timeout(20000)]):AbortSignal.timeout(20000)})}});cloud=window.ResponseDeskCloud.create(client);client.auth.onAuthStateChange((event)=>{if(event==='SIGNED_OUT'){clearPilot();notify('Signed out. Case data has been cleared from this page.');}});const {data,error}=await client.auth.getSession();if(error)throw error;if(data.session){document.getElementById('sign-out').hidden=false;await loadPilot();}}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;attempt(async()=>{
 if(b.id==='sign-out'){const {error}=await client.auth.signOut({scope:'local'});if(error)throw error;clearPilot();notify('Signed out. Case data has been cleared from this page.');return;}
 if(b.id==='refresh-pilot'){await loadPilot();notify('Latest saved cases loaded.');return;}
 if(b.id==='team-access'){await renderTeam();return;}
 if(b.dataset.view){navigate(b.dataset.view);return;}
 if(b.dataset.case){navigate('case',b.dataset.case);return;}
 if(b.id==='reset-demo'){readSequence++;cases=D.sampleCases();sequence=107;queue={openOnly:true};handover={openOnly:true};book=null;matrix=[];preview=null;navigate('today');notify('Fictional sample cases restored.');return;}
 if(b.dataset.stat){queue={openOnly:true};if(b.dataset.stat==='complaints')queue.category='Complaint';if(['overdue','unassigned'].includes(b.dataset.stat))queue[b.dataset.stat]=true;renderToday();return;}
 if(b.hasAttribute('data-toggle')){queue[b.dataset.toggle]=!queue[b.dataset.toggle];renderToday();return;}
 if(b.hasAttribute('data-clear-filters')){queue={openOnly:true};renderToday();return;}
 if(b.hasAttribute('data-scenario')){const c=cases.find(c=>c.id===selected);cases[cases.indexOf(c)]=D.apply(D.apply(c,'update',{category:'Complaint',remedy:'Replacement',nextAction:'Confirm replacement availability',due:new Date(Date.now()+24*3600000).toISOString(),state:'Needs action'}),'note',{kind:'Customer update',text:'The parcel arrived today, but the item is damaged. Maya has requested a replacement.'});renderCase();notify('Enquiry converted to complaint. The original conversation is still in the history.');return;}
 if(b.hasAttribute('data-template')){const c=cases.find(c=>c.id===selected);document.getElementById('reply-draft').value=`Hi ${c.customer.split(' ')[0]},\n\nThank you for ${c.category==='Complaint'?'letting us know about the problem. I’m sorry for the inconvenience':'your enquiry'}. I’m looking into “${c.subject}”.\n\nMy next step is to ${c.nextAction?c.nextAction[0].toLowerCase()+c.nextAction.slice(1):'[confirm the next action]'}. I will update you by ${c.due?date(c.due):'[add a realistic date/time]'}.\n\nKind regards,\n${c.owner||'[your name]'}`;notify('Editable template added. Review the details before sending.');return;}
 if(b.hasAttribute('data-copy')){const text=document.getElementById('reply-draft').value;if(!text.trim())throw Error('Write a draft before copying.');if(!navigator.clipboard){document.getElementById('reply-draft').select();throw Error('Select and copy the draft manually in this browser.');}navigator.clipboard.writeText(text).then(()=>notify('Draft copied. Paste it into your usual channel to send.')).catch(()=>{document.getElementById('reply-draft').select();notify('Copy was unavailable. The draft is selected so you can copy it manually.',true);});return;}
 if(b.hasAttribute('data-download-template')){downloadWorkbook(template(),'customer-response-import-template.xlsx');return;}
 if(b.hasAttribute('data-import-example')){loadExample();return;}
 if(b.hasAttribute('data-preview')){preview=review();renderPreview();notify(`${preview.filter(r=>r.valid).length} valid rows reviewed. Check the preview before importing.`);return;}
 if(b.hasAttribute('data-commit-import')){const latest=review(),valid=latest.filter(r=>r.valid);if(!valid.length)throw Error('No valid new rows to import.');if(cases.length+valid.length>2500)throw Error('This desk supports up to 2,500 cases.');const created=valid.map(r=>{const c=D.newCase(r.data,nextId());c.timeline.push({at:new Date().toISOString(),type:'Imported',text:`Imported from ${fileName}, worksheet ${sheetName}, row ${r.row}.`});return c;});const saved=await persist(created);cases=cases.concat(saved);preview=review();render();notify(`${saved.length} cases imported. Existing cases were not changed. Repeat references now appear as duplicates.`);return;}
 if(b.hasAttribute('data-export-review')){downloadWorkbook({Review:preview.map(r=>({Row:r.row,Reference:r.data.externalRef,Customer:r.data.customer,Subject:r.data.subject,Result:r.valid?'Ready':r.errors.join(' | '),'Next due (UTC)':r.data.due}))},'customer-response-import-review.xlsx');return;}
 if(b.hasAttribute('data-export-handover')){const items=sorted(filteredHandover()),s=D.counts(items);if(!items.length)throw Error('No open cases match this handover.');downloadWorkbook({Cases:D.exportRows(items),Handover:[['Customer Response Desk · prototype handover'],['Generated at (UTC)',new Date().toISOString()],['Display timezone',tz],['Filters',JSON.stringify(handover)],['Open cases',s.open],['Enquiries',s.enquiries],['Complaints',s.complaints],['Overdue',s.overdue],['Unassigned',s.unassigned],['Scope','Open cases matching the on-screen filters. Deadlines exported in UTC.'],['Reminder','Prototype session data; no messages or reminders have been sent.']],History:items.flatMap(c=>c.timeline.map(e=>({'Case ID':c.id,'Event time (UTC)':e.at,Type:e.type,Details:e.text})))},'customer-response-handover.xlsx');notify(`${items.length} open cases exported with next actions, deadlines and history.`);return;}
 });});
screen.addEventListener('submit',event=>{event.preventDefault();const form=event.target,p=Object.fromEntries(new FormData(form));p.confirmed=p.confirmed==='on';attempt(async()=>{
 if(form.id==='login-form'){const {error}=await client.auth.signInWithPassword({email:p.email,password:p.password});if(error)throw error;form.reset();document.getElementById('sign-out').hidden=false;await loadPilot();notify('Signed in. Cases will be saved to the pilot database.');return;}
 if(form.id==='member-form'){await cloud.members({p_email:p.p_email,p_label:p.p_label,p_role:p.p_role,p_enabled:p.p_enabled==='true'});await renderTeam();notify('Pilot access updated.');return;}
 if(form.id==='add-form'){if(p.externalRef&&cases.some(c=>c.externalRef.trim().toLowerCase()===p.externalRef.trim().toLowerCase()))throw Error('That reference already exists. Open the existing case or use a unique reference.');if(cases.length>=2500)throw Error('Case limit reached.');const c=D.newCase(p,nextId());const [saved]=await persist([c]);cases.push(saved);navigate('case',saved.id);notify('Case created with its first history event.');}
 else{const actions={'edit-form':'update','note-form':'note','draft-form':'draft','sent-form':'sent','escalate-form':'escalate','resolve-form':'resolve','reopen-form':'reopen'};if(actions[form.id])await saveAction(actions[form.id],p);}
 });});
screen.addEventListener('input',event=>{const input=event.target,g=input.closest('[data-filter-group]');if(g&&input.type==='search'){const f=g.dataset.filterGroup==='queue'?queue:handover;f.search=input.value;if(g.dataset.filterGroup==='queue')refreshQueue();else refreshHandover();}});
screen.addEventListener('change',event=>{const input=event.target;attempt(()=>{
 const g=input.closest('[data-filter-group]');if(g){const f=g.dataset.filterGroup==='queue'?queue:handover;f[input.name]=input.value;if(g.dataset.filterGroup==='queue')refreshQueue();else refreshHandover();return;}
 if(input.id==='show-resolved'){queue.openOnly=!input.checked;refreshQueue();return;}
 if(input.id==='import-sheet'){readMatrix(input.value);renderImport();return;}
 if(input.id==='import-header'){const value=Number(input.value);if(!Number.isInteger(value)||value<1||value>matrix.length)throw Error('Choose a header row within this worksheet.');header=value-1;guessMapping();preview=null;renderImport();return;}
 if(input.dataset.map){mapping[input.dataset.map]=input.value;preview=null;document.getElementById('import-review').innerHTML='';return;}
 if(input.id==='handover-from'||input.id==='handover-to'){const key=input.id==='handover-from'?'from':'to',next={...handover,[key]:input.value};if(next.from&&next.to&&next.from>next.to){input.value=handover[key]||'';throw Error('From date must be on or before the through date.');}handover=next;refreshHandover();return;}
 if(input.id==='import-file'){const file=input.files[0];if(!file)return;if(!/\.(xlsx|csv)$/i.test(file.name))throw Error('Choose an .xlsx or .csv file.');if(file.size>10*1024*1024)throw Error('Use a file smaller than 10 MB.');const ticket=++readSequence;notify('Reading file locally…');file.arrayBuffer().then(buffer=>{if(ticket!==readSequence)return;attempt(()=>{if(!X)throw Error('Excel parser did not load. Reload the page.');const bytes=new Uint8Array(buffer);if(/\.xlsx$/i.test(file.name)&&(bytes[0]!==80||bytes[1]!==75))throw Error('This file is not an .xlsx workbook. Save it as .xlsx in Excel and try again.');const nextBook=X.read(bytes,{type:'array',raw:true,cellDates:false,cellFormula:true,bookVBA:false});const chosen=nextBook.SheetNames.find(n=>/^(cases|enquiries|complaints)$/i.test(n))||nextBook.SheetNames[0];readMatrix(chosen,nextBook);fileName=file.name;if(view==='import')renderImport();notify('File opened locally. Review the worksheet, heading and column mapping in Import & review.');});}).catch(()=>{if(ticket===readSequence)notify('Could not read this file. Try a valid .xlsx or UTF-8 CSV file.',true);});}
 });});
render();if(isPilot)attempt(initPilot);
})();
